import{_ as e,o as a,c as o,a0 as i}from"./chunks/framework.DzvPB4Y-.js";const f=JSON.parse('{"title":"多箱型与目标配置：先说明“装得好”是什么意思","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/bpp3d/business-scenario.md","filePath":"zh-cn/frameworks/bpp3d/business-scenario.md"}'),d={name:"zh-cn/frameworks/bpp3d/business-scenario.md"};function r(n,t,l,s,c,h){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="多箱型与目标配置-先说明-装得好-是什么意思" tabindex="-1">多箱型与目标配置：先说明“装得好”是什么意思 <a class="header-anchor" href="#多箱型与目标配置-先说明-装得好-是什么意思" aria-label="Permalink to &quot;多箱型与目标配置：先说明“装得好”是什么意思&quot;">​</a></h1><p>在<a href="./first-loading.html">第一次三维装箱</a>接通最终选择和装载分析后，再加入第二种箱型。这个新练习只用正方体，避免让复杂朝向掩盖目标配置问题。</p><h2 id="_1-一个能区分目标的场景" tabindex="-1">1. 一个能区分目标的场景 <a class="header-anchor" href="#_1-一个能区分目标的场景" aria-label="Permalink to &quot;1. 一个能区分目标的场景&quot;">​</a></h2><p>货物为 <code>2 × 2 × 2 m</code> 正方体，共 10 件，净体积 80 m³。承重充分，不加额外间距、支撑或平衡规则：</p><table tabindex="0"><thead><tr><th>箱型</th><th>内尺寸</th><th style="text-align:right;">体积</th><th style="text-align:right;">可用箱数</th><th style="text-align:right;">单箱费用</th></tr></thead><tbody><tr><td>S</td><td>4 × 4 × 4 m</td><td style="text-align:right;">64 m³</td><td style="text-align:right;">2</td><td style="text-align:right;">4</td></tr><tr><td>L</td><td>4 × 4 × 6 m</td><td style="text-align:right;">96 m³</td><td style="text-align:right;">1</td><td style="text-align:right;">10</td></tr></tbody></table><p>一箱 S 最多放 8 件；一箱 L 可按 2×2×3 网格放 12 件，因此可以选择一箱 L，或两箱 S。体积消耗分别为 96、128 m³，费用分别为 10、8。最少箱数与最少体积消耗偏好 L，最小费用偏好两个 S。</p><p>这只是待实现的手算练习；需要用第一课的调用路径实际求解它。层生成与最终排布都必须实际包含相应可行方案。</p><h2 id="_2-多箱型有三处要同时接通" tabindex="-1">2. 多箱型有三处要同时接通 <a class="header-anchor" href="#_2-多箱型有三处要同时接通" aria-label="Permalink to &quot;2. 多箱型有三处要同时接通&quot;">​</a></h2><ol><li>生成请求携带全部箱型：Kotlin <code>Bpp3dLayerGenerationRequest.bins</code>；Rust <code>LayerGenerationRequest.bins</code>。</li><li>每列保留来源箱型，不能把同坐标、不同箱型的层合并。</li><li>最终模型有真实可用箱体：Kotlin <code>finalBins</code>；Rust 对应 final executor 的箱体输入。只增加箱型目录不等于有无限实箱，数组下标也不应成为跨请求身份。</li></ol><p>然后对同一货物 ID 设置精确 10 件需求，按第一课的请求工厂同步维护需求表示、seed 列和最终箱体。不要把一箱 S 的 8 件容量写成订单需求。</p><h2 id="_3-显式配置目标-而不是猜默认值" tabindex="-1">3. 显式配置目标，而不是猜默认值 <a class="header-anchor" href="#_3-显式配置目标-而不是猜默认值" aria-label="Permalink to &quot;3. 显式配置目标，而不是猜默认值&quot;">​</a></h2><table tabindex="0"><thead><tr><th>意义</th><th>Kotlin 配置字段</th><th>Rust 配置字段</th></tr></thead><tbody><tr><td>体积消耗权重</td><td><code>finalBinVolumeWeight</code></td><td><code>final_bin_volume_weight</code></td></tr><tr><td>箱数系数</td><td><code>finalBinAmountCoefficient</code></td><td><code>final_bin_amount_coefficient</code></td></tr><tr><td>箱型费用权重</td><td><code>finalBinTypeCostWeight</code></td><td><code>final_bin_type_cost_weight</code></td></tr><tr><td>箱型费用表</td><td><code>finalBinTypeCosts</code></td><td><code>final_bin_type_costs</code></td></tr></tbody></table><p>配置定义见 <a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp3d/bpp3d-application/src/main/fuookami/ospf/kotlin/framework/bpp3d/application/service/ColumnGenerationStandardExecutors.kt" target="_blank" rel="noreferrer">Kotlin 标准执行器</a>和 <a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp3d/src/application/service/executor/config.rs" target="_blank" rel="noreferrer">Rust 执行器配置</a>。当前默认体积权重为 1、箱数系数为 <code>1e-6</code>、费用权重为 0；只填费用表不会让费用自动主导结果。</p><p>先分别做纯目标实验：只保留体积权重，或只保留费用权重。再把箱数系数设零，研究归一化后的 <code>score = consumed_volume + λ × cost</code>：L 得分 <code>96 + 10λ</code>，两个 S 得分 <code>128 + 8λ</code>；λ=16 打平，超过 16 后费用偏好反转。这里体积数值统一按 m³ 取值，权重需要有明确换算口径。</p><p>加权和不是严格的“先体积、后费用”。若业务要求任何体积改善都优先，要采用有界、经证明的权重设计，或评估明确的分阶段固定最优值流程；不要宣称默认 <code>1e-6</code> 在所有尺度上保证词典序。</p><h2 id="_4-验收最终方案-而不是候选体积" tabindex="-1">4. 验收最终方案，而不是候选体积 <a class="header-anchor" href="#_4-验收最终方案-而不是候选体积" aria-label="Permalink to &quot;4. 验收最终方案，而不是候选体积&quot;">​</a></h2><ul><li>恰好装入 10 件，不允许一个货物在多个选层中重复兑现。</li><li>所有实际放置在箱内，不重叠，朝向、承重和启用的支撑规则合法。</li><li>按实际使用箱体重算箱数、96/128 m³ 消耗和费用；余量分别为 16/48 m³。</li><li>RMP 与 final 均使用正确扩展及后端；<code>finalSolved</code> 或对应诊断、packing snapshot 和实际放置共同检查。</li></ul><p>目标系数与实际求解范围分开记录；系数配置正确不代表候选完备，也不代表新场景已被证明全局最优。</p><p>若最小箱子单件也装不下，先查方向和候选；若候选有了但最终无方案，再查可用实箱、需求和跨层几何。按<a href="./../integration.html">接入指南</a>保存原始诊断，不要仅通过增加迭代次数排错。</p><p>源码回归命令统一放在<a href="./../verification.html">仓库验证参考</a>；先完成业务输入、调用与结果复核，再按需验证。</p>',20)])])}const m=e(d,[["render",r]]);export{f as __pageData,m as default};
